)
insert into public.college_sources (college_id, label, url, last_verified_at, source_scope)
select colleges.id, input.label, input.url, input.last_verified_at, input.source_scope
from input join public.colleges on colleges.slug = input.slug
on conflict (college_id, url) do update set
  label = excluded.label, last_verified_at = excluded.last_verified_at, source_scope = excluded.source_scope;

with input as (
  select * from jsonb_to_recordset('[{"slug":"amherst","alias":"amherst-college"},{"slug":"bowdoin","alias":"bowdoin-college"},{"slug":"brown","alias":"brown-university"},{"slug":"dartmouth","alias":"dartmouth-college"},{"slug":"harvard","alias":"harvard-university"},{"slug":"mit","alias":"massachusetts-institute-of-technology-mit"},{"slug":"princeton","alias":"princeton-university"},{"slug":"st-mary-s-university-texas","alias":"st-marya-tms-university-texas"},{"slug":"stanford","alias":"stanford-university"},{"slug":"notre-dame","alias":"university-of-notre-dame"},{"slug":"rochester","alias":"university-of-rochester"},{"slug":"usc","alias":"university-of-southern-california"},{"slug":"yale","alias":"yale-university"}]'::jsonb) as x(slug text, alias text)
)
insert into public.college_slug_aliases (alias, college_id)
select input.alias, colleges.id from input join public.colleges on colleges.slug = input.slug
on conflict (alias) do update set college_id = excluded.college_id;

commit;
